python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
wb=load_workbook('/root/data/workbook.xlsx', data_only=False)
ws=wb['Data']
print('Searching Data sheet for year header values 2019-2023 and nonblank rows 1-20:')
for r in range(1,21):
    vals=[]
    for c in range(1,27):
        v=ws.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    if vals:
        print(' | '.join(vals))
for target in [2019,2020,2021,2022,2023,'2019','2020','2021','2022','2023']:
    locs=[]
    for row in ws.iter_rows():
        for cell in row:
            if cell.value == target:
                locs.append(cell.coordinate)
    if locs:
        print(target, locs)
print('Merged cells:', list(ws.merged_cells.ranges))
print('Column dimensions hidden?')
for c in range(1,27):
    letter=get_column_letter(c)
    dim=ws.column_dimensions[letter]
    if dim.hidden or dim.width:
        print(letter, 'hidden=', dim.hidden, 'width=', dim.width)
print('Row dimensions hidden?')
for r in range(1,39):
    dim=ws.row_dimensions[r]
    if dim.hidden or dim.height:
        print(r, 'hidden=', dim.hidden, 'height=', dim.height)
